// Generated by scripts/build-help-content.mjs from content/help/. Do not edit.

export const HELP_SOURCES: Record<string, string> = {
  "change-a-route": "---\ntitle: Change a Route\nsummary: Add or remove Properties, or ask for new dates.\norder: 3\n---\n\nTo add or remove Properties on a Route you've already asked for, email [{{requestsEmail}}](mailto:{{requestsEmail}}). That email is a Route Amendment. You can send as many as you need, and we keep every one, oldest first.\n\n## What to include\n\n- **Which Route**: its route code (shown at the top of the Route, for example Route W41-26-003), or its Placement Date.\n- **What to change**: the Properties to add or take off.\n- **A revised Schedule**, if you have one. A sentence in the email is fine too.\n\n## Change a date\n\nTo move a Route's Placement Date or Pickup Date, email [{{requestsEmail}}](mailto:{{requestsEmail}}) with the route code and the date you need. We'll change it if we can, and the Route shows the new date.\n\n## When to send it\n\nSend changes as early as you can. Once signs are going up, some changes may not be possible on that day.\n\n## Seeing your changes\n\nEach Route Amendment appears in the Route's **Requests** section once we've recorded it, under your original Route Request. We then update the Route's Stops to match.\n\n## Instructions for one Route\n\nFor something that isn't a change of Properties, such as a gate code or a street to avoid, add a special instruction on the Route itself. See [Follow a Route](/customer/help/follow-a-route).\n",
  "follow-a-route": "---\ntitle: Follow a Route\nsummary: See where your signs are, Stop by Stop.\norder: 4\nscreens: /customer/routes\n---\n\n**Routes** lists every Route we've set up for you. Search by route code, then open a Route to see its detail.\n\n## On a Route\n\n- **Route status** shows where the Route is up to: signs placed first, then picked up.\n- **Placement date** and **Pickup date** are the days we plan to put your signs up and take them down. To change a date, see [Change a Route](/customer/help/change-a-route).\n- **Stops** is the number of Stops on the Route, one for each Property we visit.\n- **Signs out** is the Signs Placed: every sign put out on the Route.\n- The progress bar counts Stops placed, then Stops picked up.\n- **Signs missing** appears once collection has started, if any signs couldn't be found.\n- **Duration** shows the Billed Time once the Route is complete.\n\nThe map and the list of Stops show each Property. Tap a Stop to find it on the map.\n\n## Each Stop\n\nEach Stop shows how it's going:\n\n- **Awaiting placement**: its signs aren't up yet.\n- **Placed**: its signs are up.\n- **Awaiting pickup**: its signs are up, waiting to be collected.\n- **Picked up**: its signs have been collected.\n- **Not yet collected**: we couldn't take its signs down, for example because a gate was locked. They're still at the Property, and we'll collect them.\n- **Removed on the day**: the Stop came off the Route on the day, so its signs didn't go up.\n\nA Stop with Missing Signs shows how many couldn't be found. Missing Signs never count as Signs Collected.\n\n## Special instructions\n\nAdd anything we should know for this Route only, such as access details, extra signs or a street to avoid. You can add instructions until sign placement begins. For instructions that apply to every Route, see [Route Defaults](/customer/help/route-defaults).\n\n## When the Route is complete\n\nWe ask how it went. See [Give feedback on a Route](/customer/help/route-feedback).\n",
  "getting-started": "---\ntitle: Getting started\nsummary: How it works, from your email to the invoice.\norder: 1\nscreens: /customer/dashboard\n---\n\nWe put your signs up at the Properties you choose, then take them down again. This portal shows each Route as it happens.\n\n## How it works\n\n1. **You ask for a Route.** Email a Route Request to [{{requestsEmail}}](mailto:{{requestsEmail}}) with your Schedule attached and the dates you need. See [Request a Route](/customer/help/request-a-route).\n2. **We set it up.** The Route appears under **Routes** with its Placement Date, its Pickup Date and a Stop for each Property.\n3. **We put your signs up** on the Placement Date. You can watch each Stop being placed. See [Follow a Route](/customer/help/follow-a-route).\n4. **We collect them** on the Pickup Date.\n5. **You tell us how it went.** Once the Route is complete, we ask for your Route Feedback. See [Give feedback on a Route](/customer/help/route-feedback).\n6. **We invoice you** for the Billed Time. See [Invoices and Billed Time](/customer/help/invoices-and-billed-time).\n\nNeed to change something after you've asked? See [Change a Route](/customer/help/change-a-route).\n\n## Your dashboard\n\nThe dashboard shows this week at a glance. Account Owners see what's been invoiced and what's outstanding, and what each agent has cost. Other users see the current Route, Stops this week, signs in the field and recent Routes.\n\n## Words we use\n\nThe portal uses a few words in a particular way, such as Placement Date and Missing Signs. The [Glossary](/customer/help/glossary) explains each one.\n\nQuestions? Email [{{supportEmail}}](mailto:{{supportEmail}}).\n",
  "glossary": "---\ntitle: Glossary\nsummary: The words this portal uses, and what they mean.\norder: 11\n---\n\n**Route**: one sign run for you: we put your signs up at a set of Properties, then take them down.\n\n**Stop**: one visit to a Property on a Route, where we put signs up and later take them down.\n\n**Property**: a real address. Many Stops, on many Routes, can be at the same Property.\n\n**Placement Date**: the day we plan to put a Route's signs up.\n\n**Pickup Date**: the day we plan to take a Route's signs down. It's set from what you asked for, or from your sign collection day.\n\n**Route Request**: your email asking us to set up one Route, usually with its Schedule attached. See [Request a Route](/customer/help/request-a-route).\n\n**Route Amendment**: a later email adding or removing Properties on a Route you've already asked for. See [Change a Route](/customer/help/change-a-route).\n\n**Schedule**: the file you send listing the Properties for a Route. We keep it exactly as you sent it.\n\n**Signs Placed**: every sign put out on a Route, shown as **Signs out**.\n\n**Signs Collected**: the signs we brought back, not counting Missing Signs or signs not yet collected.\n\n**Missing Signs**: signs we couldn't find when we went to collect them.\n\n**Couldn't Collect**: a Stop whose signs we couldn't take down, for example because a gate was locked. It shows as **not yet collected**. The signs are still at the Property, and we'll collect them.\n\n**Removed Stop**: a Stop that came off the Route on the day, so its signs didn't go up. It shows as **removed on the day**.\n\n**Billed Time**: what you're charged for a Route. See [Invoices and Billed Time](/customer/help/invoices-and-billed-time).\n\n**Route Feedback**: your answer to \"How did this route go?\" once a Route is complete. See [Give feedback on a Route](/customer/help/route-feedback).\n\n**Account Owner**: a user who can see invoices and billing, and manage Route Defaults and Property History Reports.\n\n**Route Defaults**: what every new Route we set up for you starts from. See [Route Defaults](/customer/help/route-defaults).\n",
  "invoices-and-billed-time": "---\ntitle: Invoices and Billed Time\nsummary: What you're charged for a Route, and where your invoices go.\norder: 6\nrole: account_owner\nscreens: /customer/invoices, /customer/billing-details\n---\n\n## Billed Time\n\nBilled Time is what you're charged for a Route. It's the time spent on each part of the Route (loading your signs, putting them up, taking them down and returning them).\n\n- The total is rounded to a 15-minute step.\n\nIt's set when the Route is complete, and it shows as **Duration** on the Route.\n\n## Invoices\n\n**Invoices** lists your invoices. Filter them by date, then open one to see its itemised charges. We also email a PDF the morning after the Route is completed.\n\n## Billing Details\n\n**Billing Details** shows where your invoices go and who pays them:\n\n- **Billing email**: where we send each invoice, plus any addresses to copy it to.\n- **Billing address**: the address printed on your invoices.\n- **How you pay**: set up by us. Ask us to change it.\n\nQuestions about an invoice? Email [{{billingEmail}}](mailto:{{billingEmail}}).\n",
  "property-history": "---\ntitle: Property History\nsummary: Every time we've been to a suburb, street or address.\norder: 9\nflag: property-history\nscreens: /customer/property-history\n---\n\nProperty History lists your Visits: each time one of your Routes had a Stop at a Property.\n\n## Search\n\n1. Start typing a suburb, street or address, then pick one from the suggestions.\n2. Narrow it down by date, agent or auction if you like.\n\nEach Visit links to its Route. Upcoming Routes are listed separately as scheduled.\n\n## Property History Reports\n\nAccount Owners can save a search as a Property History Report: search, then select the PDF button above the results. The report is a PDF snapshot of that search on the day you made it.\n\nThe **Reports** tab lists your reports. Each one is kept for 30 days, and you can remove one sooner.\n",
  "request-a-route": "---\ntitle: Request a Route\nsummary: Email us your Schedule and the dates you need.\norder: 2\nscreens: /customer/calendar\n---\n\nTo ask for a Route, send an email to [{{requestsEmail}}](mailto:{{requestsEmail}}). That email is your Route Request. Send one email for each Route.\n\n## What to include\n\n- **Your Schedule**: the file listing the Properties, usually a spreadsheet saved as a PDF. Attach it to the email.\n- **The Placement Date**: the day you want your signs to go up.\n- **The Pickup Date**: the day you want them taken down. If you leave it out, we'll use your sign collection day from Route Defaults, or the day after the Placement Date.\n- Anything we should know, such as how many signs go at each Property.\n\n## Before you choose dates\n\nThe **Calendar** shows the days we can't put signs up or take them down, and the days your agency is closed. Pick a Placement Date and a Pickup Date that aren't marked.\n\nAccount Owners can mark a day closed on the Calendar, with a reason if you like, so we know not to plan anything for you that day. Select the day, then **Mark closed**.\n\n## What happens next\n\nWe set up the Route from your Schedule. It appears under **Routes**, and its **Requests** section keeps your email as we received it: who sent it, when, and the attached Schedule.\n\nWe keep your Schedule exactly as you sent it. If something needs to change, send a Route Amendment instead of editing the Schedule. See [Change a Route](/customer/help/change-a-route).\n",
  "route-defaults": "---\ntitle: Route Defaults\nsummary: What every new Route we set up for you starts from.\norder: 7\nrole: account_owner\nscreens: /customer/route-defaults\n---\n\nYour Route Defaults apply to every new Route we set up for you. We can still change them on any single Route.\n\n## What you can set\n\n- **Standing instructions**: instructions for every Route, such as gate codes or where to put signs.\n- **Default signs per Stop**: how many signs go at each Property.\n- **Standing sign collection day**: the weekday you usually want your signs collected. We'll plan sign collection for the next one after your signs go up. Choose **No preference** to have them collected the day after they go up. Changing it never moves a Route we've already set up.\n\nSelect **Save Route Defaults** when you're done. Changes apply from the next Route.\n\nIf we've switched on the Missing Signs Report for you, a switch here turns that email on or off. Once a Route is finished, it lists each Property where signs went missing. It's only sent when some are.\n\n## Agents\n\nAgents on this account lists the agent codes we use to label each Stop. To change them, email [{{supportEmail}}](mailto:{{supportEmail}}).\n\nFor instructions about one Route only, add a special instruction on that Route. See [Follow a Route](/customer/help/follow-a-route).\n",
  "route-feedback": "---\ntitle: Give feedback on a Route\nsummary: Tell us how a completed Route went.\norder: 5\n---\n\nOnce a Route is complete, its page asks **How did this route go?** Your answer is your Route Feedback.\n\n- Choose **All good** if everything went as it should. That's all you need to do.\n- Choose **Something was off** if it didn't, say what, for example \"Two signs at 5 Kent St were facing the wrong way\", then select **Send feedback**.\n\nYou can change your answer until the Route has been invoiced.\n",
  "settings": "---\ntitle: Settings\nsummary: Your name, theme and map.\norder: 10\nscreens: /customer/settings\n---\n\n**Settings** changes how the portal looks for you. It doesn't affect anyone else on your account.\n\n- **Name**: how your name appears in the portal.\n- **Default Theme**: light or dark.\n- **Map Theme**: how maps look, for example on a Route.\n\nSave your changes and they apply straight away.\n",
  "users": "---\ntitle: Users\nsummary: Who can sign in to your portal.\norder: 8\nrole: account_owner\nscreens: /customer/users\n---\n\n**Users** lists everyone who can sign in to your portal.\n\n## Two kinds of user\n\n- **Account Owner**: sees everything, including invoices and billing, and manages Route Defaults and Property History Reports.\n- **Read only**: sees Routes and Stops only.\n\n:::if account-owner-invite\n## Add a user\n\n1. Enter their email and, if you like, a display name.\n2. Select **Send invite**.\n\nThey'll get an email with a temporary password and set their own when they first sign in. New users are read only. To make someone an Account Owner, email [{{supportEmail}}](mailto:{{supportEmail}}).\n:::else\n## Add a user\n\nEmail [{{supportEmail}}](mailto:{{supportEmail}}) with their name and email address, and say whether they should be an Account Owner.\n:::end\n\n## Remove a user\n\nEmail [{{supportEmail}}](mailto:{{supportEmail}}) and we'll remove their access.\n",
};
